// Program, commercial and measurement guides checked against official sources on 2026-10-15.
const pair = (zh, en) => [zh, en];
const section = (zhTitle, enTitle, zh, en, citations = []) => [pair(zhTitle, enTitle), pair(zh, en), citations];
const source = (id, zh, en, url) => ({ id, terms: pair(zh, en), label: pair(zh, en), url });
